static bool frag_acc_ensure(struct frag_acc *acc, uint16_t max_total)
{
  if (acc->data != NULL)
    {
      return true;
    }

  acc->data = board_malloc_psram(max_total);
  if (acc->data == NULL)
    {
      return false;
    }

  memset(acc->data, 0, max_total);
  return true;
