static int name_is_bin(const char *name)
{
  size_t n;

  if (name == NULL)
    {
      return 0;
    }

  n = strlen(name);
  if (n < 5 || n >= MYVENDOR_FW_SLOT_NAME_MAX)
    {
      return 0;
    }

  return name[n - 4] == '.' &&
         (name[n - 3] == 'b' || name[n - 3] == 'B') &&
         (name[n - 2] == 'i' || name[n - 2] == 'I') &&
         (name[n - 1] == 'n' || name[n - 1] == 'N');
}

